"""SQLite 台账持久化。

台账包含两张表：

- ``windows``：每日服务时段（本地挂钟时间 ``HH:MM``）；
- ``tickets``：工单及其受理时刻与计算出的响应截止时刻。

工单写入在单个事务内完成，任何校验失败都不会留下半条记录。
"""

import datetime as _dt
import sqlite3
from collections.abc import Iterator
from contextlib import contextmanager
from pathlib import Path

from . import sla

SCHEMA = """
CREATE TABLE IF NOT EXISTS windows (
    id      TEXT PRIMARY KEY,
    start   TEXT NOT NULL,
    "end"   TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS tickets (
    id          TEXT PRIMARY KEY,
    priority    TEXT NOT NULL,
    window_id   TEXT NOT NULL REFERENCES windows(id),
    created_at  TEXT NOT NULL,
    deadline    TEXT NOT NULL
);
"""


class LedgerError(Exception):
    """台账操作失败（重复 id、外键缺失等）。"""


class NotFound(LedgerError):
    """查询的记录不存在。"""


class DuplicateRecord(LedgerError):
    """id 已存在；退出码按 2 处理。"""


@contextmanager
def connect(db_path: str | Path) -> Iterator[sqlite3.Connection]:
    """打开（必要时创建）台账，成功时提交，异常时回滚。"""
    path = Path(db_path)
    if path.parent and not path.parent.exists():
        raise LedgerError(f"台账目录不存在: {path.parent}")
    conn = sqlite3.connect(str(path))
    conn.execute("PRAGMA foreign_keys = ON")
    try:
        conn.executescript(SCHEMA)
        yield conn
        conn.commit()
    except BaseException:
        conn.rollback()
        raise
    finally:
        conn.close()


def create_window(
    conn: sqlite3.Connection, window_id: str, start: _dt.time, end: _dt.time
) -> None:
    try:
        conn.execute(
